int: n = 6; % number of countries
set of int: Countries = 1..n;

% adjacency list given as pairs (i,j)
array[1..9, 1..2] of int: graph = [
    | 3, 1
    | 3, 6
    | 3, 4
    | 6, 4
    | 6, 1
    | 1, 5
    | 1, 4
    | 4, 5
    | 4, 2
];

% variables: color assigned to each country
