int: num_cows = 25;
int: num_sons = 5;

array[1..num_cows] of int: milk = [i | i in 1..num_cows];
array[0..num_sons-1] of int: cows_per_son = [7,6,5,4,3];

% Decision variables: for each cow, which son it is assigned to (0..4)
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Each son must get exactly the specified number of cows
constraint
  forall(s in 0..num_sons-1) (
    sum([bool2int(cow_assignments[c] == s) | c in 1..num_cows]) == cows_per_son[s+1]
  );

% The total milk per son must be equal
array[0..num_sons-1] of var int: milk_per_son = [
  sum([milk[c] * bool2int(cow_assignments[c] == s) | c in 1..num_cows]) | s in 0..num_sons-1
];

constraint
  forall(s in 1..num_sons-1) (
    milk_per_son[s] == milk_per_son[0]
  );

solve satisfy;

output [
  "{",
  "\"cow_assignments\": [" ++ join(", ", [show(cow_assignments[c]) | c in 1..num_cows]) ++ "]",
  "}"
];
```

