% The prices of the four items in cents
array[1..4] of var 1..711: prices;

% The sum of the prices is 711 cents ($7.11)
constraint sum(prices) == 711;

% The product of the prices is 711000000 (since prices are in cents, product is in cents^4)
% 7.11 dollars = 711 cents, so product in cents^4 is 711^4
constraint
  let {
    var int: p = prices[1] * prices[2] * prices[3] * prices[4]
  } in
    p == 711000000;

% To avoid symmetric solutions, enforce non-decreasing order
constraint forall(i in 1..3) (prices[i] <= prices[i+1]);

solve satisfy;

output [
    "{",
    "\"prices\": [" ++ join(", ", [show(prices[i]) | i in 1..4]) ++ "]",
    "}"
];
```

