```minizinc
int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

array[1..num_people, 1..num_people] of var 0..1: transplants;

// Constraint: transplants[i][j] can be 1 only if j in compatible[i]
constraint
  forall(i in 1..num_people, j in 1..num_people) (
    transplants[i,j] = 1 -> j in compatible[i]
  );

// Constraint: no person receives more than one kidney
constraint
  forall(j in 1..num_people) (
    sum(i in 1..num_people)(transplants[i,j]) <= 1
  );

// Constraint: anyone who gives a kidney must receive one
// i.e. for each person i, sum of row i (gives) = sum of column i (receives)
constraint
  forall(i in 1..num_people) (
    sum(j in 1..num_people)(transplants[i,j]) = sum(j in 1..num_people)(transplants[j,i])
  );

// Objective: maximize the number of people that receive a kidney
// This is sum over j of sum over i transplants[i,j], which equals sum over i of sum over j transplants[i,j]
// because of the previous constraint, so we can sum over either rows or columns
var int: total_transplants = sum(i,j in 1..num_people)(transplants[i,j]);
solve maximize total_transplants;

output [
    "[",
    concat([
      "[" ++ join(", ", [show(transplants[i,j]) | j in 1..num_people]) ++ "]" ++ if i < num_people then ",\n" else "\n" endif
      | i in 1..num_people
    ]),
    "]"
];
```

