% Main diagonal sums to magic_sum
constraint
  sum(i in 1..n)(square[i,i]) == magic_sum;

% Secondary diagonal sums to magic_sum
constraint
  sum(i in 1..n)(square[i,n+1 - i]) == magic_sum;

solve satisfy;

output [
  "{",
  "\"square\": [",
  join(",\n", [
    "[" ++ join(", ", [show(square[i,j]) | j in 1..n]) ++ "]"
    | i in 1..n
  ]),
  "]",
  "}"
];
