int: n = 8;
array[1..n] of array[int] of int: adjacency_list = [
    [2, 3, 7],
    [1, 4, 8],
    [1, 4, 5],
    [2, 3, 6],
    [3, 6, 7],
    [4, 5, 8],
    [1, 5, 8],
    [2, 6, 7]
];

array[1..n] of var bool: nodes;

// Constraint: no two adjacent nodes can both be in the independent set
constraint
    forall(i in 1..n, j in adjacency_list[i]) (
        nodes[i] + nodes[j] <= 1
    );

// Constraint: maximality - for every node not in the set, at least one neighbor is in the set
constraint
    forall(i in 1..n) (
        if not nodes[i] then
            exists(j in adjacency_list[i]) (nodes[j])
        else
            true
        endif
    );

solve satisfy;

output [
    "{",
    join(",", [ "\"" ++ show(i) ++ "\": " ++ show(nodes[i]) | i in 1..n ]),
    "}"
];
```

