int: num_males = 4;
int: num_females = num_people - num_males;

array[1..num_people] of var 0..1: sequence;

% Count males and females in the sequence
% 0 = male, 1 = female

% Constraint: exactly num_males males and num_females females
constraint
    sum(i in 1..num_people)(sequence[i] == 0) == num_males /\
    sum(i in 1..num_people)(sequence[i] == 1) == num_females;

% At any time t, ratio females/males <= 7/3
% For t in 1..num_people:
% Let fm = number of females entered so far
% Let mm = number of males entered so far
% If mm == 0, ratio is infinite, so females must be 0 at that time (no females before any male)
% Otherwise, fm/mm <= 7/3  <=> 3*fm <= 7*mm

constraint
    forall(t in 1..num_people) (
        let {
            var int: fm = sum(i in 1..t)(sequence[i] == 1),
            var int: mm = sum(i in 1..t)(sequence[i] == 0)
        } in
        (mm == 0 -> fm == 0) /\
        (mm > 0 -> 3 * fm <= 7 * mm)
    );

solve satisfy;

output [
    "{",
    "\"sequence\": [" ++ join(", ", [show(sequence[i]) | i in 1..num_people]) ++ "]",
    "}"
];
```

