enum SUSPECTS = {artie, bill, crackitt, dodgy, edgy, fingers};

% Variables: guilty or not for each suspect
array[SUSPECTS] of var bool: guilty;

% At least four are innocent
constraint sum([bool2int(guilty[s]) | s in SUSPECTS]) <= 2;

% Innocent tell the truth, guilty lie
% Define the statements as boolean expressions

% ARTIE: "It wasn't me."
% Artie says he is innocent
constraint (guilty[artie] = false) <-> (guilty[artie] = false);

% BILL: "Crackitt was in it up to his neck."
% Bill says Crackitt is guilty
constraint (guilty[bill] = false) <-> (guilty[crackitt] = true);

% CRACKITT: "No I wasn't."
% Crackitt says he is innocent
constraint (guilty[crackitt] = false) <-> (guilty[crackitt] = false);

% DODGY: "If Crackitt did it, Bill did it with him."
% If Crackitt guilty then Bill guilty
constraint (guilty[dodgy] = false) <-> (guilty[crackitt] -> guilty[bill]);

% EDGY: "Nobody did it alone."
% No one is alone, i.e. no guilty person alone
% For every guilty person, there is at least one other guilty person
% So if guilty[s], then sum of guilty >= 2
constraint (guilty[edgy] = false) <-> forall(s in SUSPECTS) (
    guilty[s] -> (sum([bool2int(guilty[x]) | x in SUSPECTS]) >= 2)
);

% FINGERS: "That’s right: it was Artie and Dodgy together."
% Fingers says the guilty are exactly Artie and Dodgy
constraint (guilty[fingers] = false) <-> (
    forall(s in SUSPECTS) (
        (s == artie \/ s == dodgy) <-> guilty[s]
    )
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"artie\": " ++ show(guilty[artie]),
