```minizinc
int: n = 6;
array[1..n] of int: demands = [4, 8, 10, 7, 12, 4];

// Decision variables: number of buses starting their 8-hour shift at each 4-hour interval
// Since each bus works 8 successive hours = 2 intervals, a bus starting at interval i covers intervals i and i+1
// We consider shifts starting at intervals 1 to n-1 (since last interval n cannot start a new 8-hour shift)
array[1..n-1] of var 0..sum(demands): x;

// For each interval, sum of buses covering it must be >= demand
// Interval i is covered by buses starting at i-1 and i (if those indices exist)
constraint
  forall(i in 1..n) (
    let {
      var int: cover_prev = if i-1 >= 1 then x[i-1] else 0 endif,
      var int: cover_curr = if i <= n-1 then x[i] else 0 endif
    } in
    cover_prev + cover_curr >= demands[i]
  );

// Objective: minimize total number of buses scheduled
var int: total_buses = sum(i in 1..n-1)(x[i]);
solve minimize total_buses;

output [
  "{",
  join(",", [
    "\"" ++ "x" ++ show(i) ++ "\": " ++ show(x[i]) | i in 1..n-1
  ]),
  "}"
];
```

