include "globals.mzn";

int: num_jobs = 3;
int: num_machines = 3;

% Input data: for each job, a list of (machine, duration) pairs for its tasks
array[1..num_jobs] of array[int] of tuple(machine: int, duration: int): jobs_data = [
    [(1,3), (2,2), (3,2)],
    [(1,2), (3,1), (2,4)],
    [(2,4), (3,3)]
];

% Number of tasks per job
array[1..num_jobs] of int: num_tasks = [length(jobs_data[j]) | j in 1..num_jobs];

% Compute horizon as sum of all durations (upper bound on makespan)
int: horizon = sum(j in 1..num_jobs, t in 1..num_tasks[j]) (jobs_data[j][t].duration);

% Variables: start time of each task
array[1..num_jobs, int] of var 0..horizon: start;

% Variables: end time of each task
array[1..num_jobs, int] of var 0..horizon: end;

% Define end times
constraint
  forall(j in 1..num_jobs, t in 1..num_tasks[j]) (
    end[j,t] = start[j,t] + jobs_data[j][t].duration
  );

% Precedence constraints: tasks in a job must be done in order
constraint
  forall(j in 1..num_jobs, t in 1..num_tasks[j]-1) (
    end[j,t] <= start[j,t+1]
  );

% Collect all tasks on each machine
% For each machine, get the list of (job, task) pairs that run on it
array[1..num_machines] of array[int] of tuple(job: int, task: int): machine_tasks = 
  [ 
    [ (j,t) | j in 1..num_jobs, t in 1..num_tasks[j] where jobs_data[j][t].machine == m ] 
    | m in 1..num_machines
  ];

% Disjunctive constraints: no overlap on the same machine
constraint
  forall(m in 1..num_machines) (
    forall(i,j in 1..length(machine_tasks[m]) where i < j) (
      let {
        var int: s1 = start[machine_tasks[m][i].job, machine_tasks[m][i].task],
        var int: e1 = end[machine_tasks[m][i].job, machine_tasks[m][i].task],
        var int: s2 = start[machine_tasks[m][j].job, machine_tasks[m][j].task],
        var int: e2 = end[machine_tasks[m][j].job, machine_tasks[m][j].task]
      } in
        (e1 <= s2) \/ (e2 <= s1)
    )
  );

% Makespan: max of all end times
var 0..horizon: makespan;
constraint
  makespan = max([end[j,t] | j in 1..num_jobs, t in 1..num_tasks[j]]);

% Objective: minimize makespan
solve minimize makespan;

output [
  "{",
  "\"makespan\": " ++ show(makespan),
  "}"
];
