include "globals.mzn";

int: n_rows = 8;
int: n_cols = 8;
int: X = -1;

array[1..n_rows, 1..n_cols] of int: game_data = [
    |  2,  3,  X,  2,  2,  X,  2,  1
    |  X,  X,  4,  X,  X,  4,  X,  2
    |  X,  X,  X,  X,  X,  X,  4,  X
    |  X,  5,  X,  6,  X,  X,  X,  2
    |  2,  X,  X,  X,  5,  5,  X,  2
    |  1,  3,  4,  X,  X,  X,  4,  X
    |  0,  1,  X,  4,  X,  X,  X,  3
    |  0,  1,  2,  X,  2,  3,  X,  2
];

// Decision variables: for each cell, whether it is a mine (true) or not (false)
array[1..n_rows, 1..n_cols] of var bool: mines;

// Helper function: get neighbors of a cell (r,c)
function array[int] of tuple(int,int) : neighbors(int: r, int: c) =
    [ (rr,cc) |
        rr in max(1,r-1)..min(n_rows,r+1),
        cc in max(1,c-1)..min(n_cols,c+1),
        not (rr == r /\ cc == c)
    ];

// Constraints:
// For each cell with a clue (0..8), the number of mines in neighbors must equal the clue
constraint
    forall(r in 1..n_rows, c in 1..n_cols where game_data[r,c] != X) (
        let {
            array[int] of tuple(int,int): nb = neighbors(r,c)
        } in
            sum([bool2int(mines[rr,cc]) | (rr,cc) in nb]) == game_data[r,c]
    );

// For cells that are opened (game_data != X), they cannot be mines
constraint
    forall(r in 1..n_rows, c in 1..n_cols where game_data[r,c] != X) (
        mines[r,c] == false
    );

// Solve satisfy
solve satisfy;

// Output mines as JSON array of arrays of booleans
output [
    "{",
    "\"mines\": [",
    concat([
        "[" ++ join(",", [ if mines[r,c] then "true" else "false" endif | c in 1..n_cols ]) ++ "]"
        | r in 1..n_rows
    ] where r < n_rows) ++ ",",
    "[" ++ join(",", [ if mines[n_rows,c] then "true" else "false" endif | c in 1..n_cols ]) ++ "]",
    "]",
    "}"
];
