      room_assignments[i] = preassigned_room[i]
    else
      true
    endif
  );

% No overlapping requests in the same room
constraint
  forall(i, j in 1..num_requests where i < j) (
    if (start[i] < end_[j] /\ start[j] < end_[i]) then
      room_assignments[i] != room_assignments[j]
    else
      true
    endif
  );

solve satisfy;

output [
  "{",
  "\"room_assignments\": [" ++ join(", ", [show(room_assignments[i]) | i in 1..num_requests]) ++ "]",
  "}"
];
