constraint
  forall(o in 1..num_options) (
    forall(i in 1..total_cars - per_slots[o] + 1) (
      sum([requires[sequence[j]+1, o] | j in i..i+per_slots[o]-1]) <= at_most[o]
    )
  );

solve satisfy;

output [
  "{",
  "\"sequence\": [" ++ join(", ", [show(sequence[i]) | i in 1..total_cars]) ++ "]",
  "}"
];
