include "globals.mzn";

int: n_slots = 9;
int: n_templates = 2;
int: n_var = 7;
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];

// Variables:
// layout[t,v] = number of copies of variation v on template t
array[1..n_templates, 1..n_var] of var 0..n_slots: layout;

// Each template can have at most n_slots items printed on it
constraint
  forall(t in 1..n_templates) (
    sum(v in 1..n_var)(layout[t,v]) <= n_slots
  );

// The total production for each variation must meet or exceed demand
// production[v] = total number of copies produced for variation v
array[1..n_var] of var 0..sum(demand): production;
constraint
  forall(v in 1..n_var) (
    production[v] = sum(t in 1..n_templates)(layout[t,v] * n_slots)
  );

// The total production for each variation must be at least the demand
constraint
  forall(v in 1..n_var) (
    production[v] >= demand[v]
  );

// Objective: minimize total number of printed sheets (sum over templates of max sheets needed per template)
// For each template, the number of sheets needed is the max over variations of ceil(demand[v]/layout[t,v]) if layout[t,v]>0
// But since layout[t,v] is number of copies per sheet, sheets needed for variation v on template t is ceil(production[v]/layout[t,v])
// We can approximate by computing sheets per template as max over v of ceil(production[v]/layout[t,v]) if layout[t,v]>0, else 0
// To linearize, we introduce sheets_per_template[t] variables

array[1..n_templates] of var 0..sum(demand): sheets_per_template;

constraint
  forall(t in 1..n_templates) (
    sheets_per_template[t] >= 0 /\
    forall(v in 1..n_var) (
      (layout[t,v] > 0) -> (sheets_per_template[t] * layout[t,v] >= production[v])
    )
  );

// Total production sheets is sum of sheets_per_template
var 0..sum(demand)*n_templates: total_sheets = sum(t in 1..n_templates)(sheets_per_template[t]);

solve minimize total_sheets;

output [
  "{",
  "\"production\": " ++ show(total_sheets) ++ ",",
  "\"layout\": [",
  join(",\n", [
    "[" ++ join(", ", [show(layout[t,v]) | v in 1..n_var]) ++ "]"
    | t in 1..n_templates
  ]),
  "]",
  "}"
];
