% Variables: positions of the marks on the ruler
array[1..size] of var 0..10000: marks;

% The first mark is at 0
constraint marks[1] = 0;

% Marks are strictly increasing
constraint forall(i in 1..size-1) (
    marks[i] < marks[i+1]
);

% Compute all differences a_j - a_i for 1 <= i < j <= size
set of int: diff_indices = { (i,j) | i,j in 1..size where i < j };
array[diff_indices] of var int: diffs = [marks[j] - marks[i] | (i,j) in diff_indices];

