include "globals.mzn";

int: deck_width = 5;
int: deck_length = 5;
int: n_containers = 3;
array[1..n_containers] of int: width = [5, 2, 3];
array[1..n_containers] of int: length = [1, 4, 4];
array[1..n_containers] of int: classes = [1, 1, 1];
int: n_classes = 2;  % from separation matrix size
array[1..n_classes, 1..n_classes] of int: separation = [
    | 0, 0
    | 0, 0
];

% Variables: position of each container (left, bottom)
array[1..n_containers] of var 0..deck_width: left;
array[1..n_containers] of var 0..deck_length: bottom;

% Derived positions
array[1..n_containers] of var 0..deck_width: right;
array[1..n_containers] of var 0..deck_length: top;

constraint
    forall(i in 1..n_containers) (
        right[i] = left[i] + width[i] /\
        top[i] = bottom[i] + length[i] /\
        right[i] <= deck_width /\
        top[i] <= deck_length
    );

% No overlap constraints
constraint
    forall(i, j in 1..n_containers where i < j) (
        left[i] + width[i] <= left[j] \/
        left[j] + width[j] <= left[i] \/
        bottom[i] + length[i] <= bottom[j] \/
        bottom[j] + length[j] <= bottom[i]
    );

% Separation constraints between classes
% For each pair of containers i,j, if classes differ, enforce separation distances
constraint
    forall(i, j in 1..n_containers where i < j) (
        let {
            int: c1 = classes[i],
            int: c2 = classes[j],
            int: sep = separation[c1, c2]
        } in
        if sep > 0 then
            (left[i] + width[i] + sep <= left[j]) \/
            (left[j] + width[j] + sep <= left[i]) \/
            (bottom[i] + length[i] + sep <= bottom[j]) \/
            (bottom[j] + length[j] + sep <= bottom[i])
        else
            true
        endif
    );

% Loading sequence constraints:
% Each container after the first must touch another container or deck wall to the north and west.
% "North" means container or deck wall is directly above (top side aligned with bottom side of another container or deck wall)
% "West" means container or deck wall is directly left (left side aligned with right side of another container or deck wall)
%
% We interpret "touches part of another container or deck wall both to the north and to the west" as:
% For container i > 1:
%   There exists some container j (or deck wall) such that:
%     - north contact: bottom[i] = top[j] and horizontal intervals overlap
%     - west contact: left[i] = right[k] and vertical intervals overlap
%   or contact with deck wall:
%     - north contact with deck wall: bottom[i] = 0 (deck wall at bottom)
%     - west contact with deck wall: left[i] = 0 (deck wall at left)
%
% Since loading is from southeast corner, container 1 can be placed anywhere.

constraint
    forall(i in 2..n_containers) (
        let {
            % north contact: bottom[i] = top[j] and horizontal overlap
            set of int: north_contacts = { j | j in 1..n_containers where j != i /\ bottom[i] = top[j] /\
                (left[i] < right[j] /\ right[i] > left[j]) },
            % west contact: left[i] = right[k] and vertical overlap
            set of int: west_contacts = { k | k in 1..n_containers where k != i /\ left[i] = right[k] /\
                (bottom[i] < top[k] /\ top[i] > bottom[k]) }
        } in
        (
            (bottom[i] = 0 \/ card(north_contacts) > 0) /\
            (left[i] = 0 \/ card(west_contacts) > 0)
        )
    );

solve satisfy;

output [
    "{",
    join(",", [
        "\"" ++ show(i) ++ "\": {"
        ++ "\"left\": " ++ show(left[i]) ++ ", "
        ++ "\"right\": " ++ show(right[i]) ++ ", "
        ++ "\"top\": " ++ show(top[i]) ++ ", "
        ++ "\"bottom\": " ++ show(bottom[i])
        ++ "}"
        | i in 1..n_containers
    ]),
    "}"
];
