int: base = 6;
array[1..9] of int: sides = [3,3,3,2,1,1,1,1,1];
int: n = length(sides);

array[1..n] of var 0..base: x_coords;
array[1..n] of var 0..base: y_coords;

// Each square must be inside the big square
constraint
  forall(i in 1..n) (
    x_coords[i] + sides[i] <= base /\
    y_coords[i] + sides[i] <= base
  );

// No overlap between squares
constraint
  forall(i,j in 1..n where i < j) (
    x_coords[i] + sides[i] <= x_coords[j] \/
    x_coords[j] + sides[j] <= x_coords[i] \/
    y_coords[i] + sides[i] <= y_coords[j] \/
    y_coords[j] + sides[j] <= y_coords[i]
  );

// The sum of the areas of the small squares equals the area of the big square
constraint
  sum(i in 1..n)(sides[i]*sides[i]) = base*base;

// Since the problem states all squares have different sizes for perfect placement,
// but input has repeated sizes, we do not enforce distinct sizes here.

// Solve satisfy to find any feasible placement
solve satisfy;

output [
  "{",
  "\"x_coords\": [" ++ join(", ", [show(x_coords[i]) | i in 1..n]) ++ "],",
  "\"y_coords\": [" ++ join(", ", [show(y_coords[i]) | i in 1..n]) ++ "]",
  "}"
];
