include "globals.mzn";

int: n_weeks = 4;    % Number of weeks
int: n_groups = 3;   % Number of groups per week
int: group_size = 3; % Number of golfers per group
int: n_golfers = n_groups * group_size;

% Variables:
% assign[w,g,p] = golfer assigned to position p in group g in week w
array[1..n_weeks, 1..n_groups, 1..group_size] of var 1..n_golfers: assign;

% Each golfer plays exactly once per week
constraint
  forall(w in 1..n_weeks) (
    % all golfers assigned in week w are all different
    alldifferent([assign[w,g,p] | g in 1..n_groups, p in 1..group_size])
  );

% Within each group, all golfers are distinct (redundant due to alldifferent above, but kept for clarity)
constraint
  forall(w in 1..n_weeks, g in 1..n_groups) (
    alldifferent([assign[w,g,p] | p in 1..group_size])
  );

% No pair of golfers plays together more than once
% For each pair of golfers (i,j), count how many times they appear in the same group over all weeks
% This count must be <= 1

% We create a helper function to check if two golfers appear together in a group
function var bool: together_in_group(int: w, int: g, int: i, int: j) =
  exists(p1 in 1..group_size, p2 in 1..group_size where p1 != p2) (
    (assign[w,g,p1] == i /\ assign[w,g,p2] == j)
  );

% For all pairs i<j, sum over weeks and groups of together_in_group <= 1
constraint
  forall(i,j in 1..n_golfers where i < j) (
    sum(w in 1..n_weeks, g in 1..n_groups) (
      bool2int(together_in_group(w,g,i,j))
    ) <= 1
  );

% Symmetry breaking: order golfers in each group ascending
constraint
  forall(w in 1..n_weeks, g in 1..n_groups, p in 1..group_size-1) (
    assign[w,g,p] < assign[w,g,p+1]
  );

% Symmetry breaking: order groups in each week by first golfer
constraint
  forall(w in 1..n_weeks, g in 1..n_groups-1) (
    assign[w,g,1] < assign[w,g+1,1]
  );

solve satisfy;

output [
  "{",
  "\"assign\": [",
  concat([
    "{"
    ++ "\"week\": " ++ show(w) ++ ", "
    ++ "\"groups\": ["
    ++ concat([
      "{"
      ++ "\"group\": " ++ show(g) ++ ", "
      ++ "\"players\": [" ++ join(", ", [show(assign[w,g,p]) | p in 1..group_size]) ++ "]"
      ++ "}"
      | g in 1..n_groups
    ])
    ++ "]"
    ++ "}"
    | w in 1..n_weeks
  ]),
  "]",
  "}"
];
