include "globals.mzn";

int: n_teams = 9;
int: n_days = 18;

set of int: TEAMS = 1..n_teams;
set of int: DAYS = 1..n_days;

% Team names for output clarity
array[TEAMS] of string: team_names = ["Clem", "Duke", "FSU", "GT", "UMD", "UNC", "NCSt", "UVA", "Wake"];

% Mirroring pairs (r1,r2)
array[1..9, 1..2] of int: mirror_pairs = array2d(1..9, 1..2,
  [1,8, 2,9, 3,12, 4,13, 5,14, 6,15, 7,16, 10,17, 11,18]);

% Rival pairs (except FSU)
% Duke-UNC, Clem-GT, NCSt-Wake, UMD-UVA
% Map team to rival (0 if none)
array[TEAMS] of int: rival = [
  4,  % Clem -> GT
  6,  % Duke -> UNC
  0,  % FSU no rival
  1,  % GT -> Clem
  9,  % UMD -> UVA
  2,  % UNC -> Duke
  9,  % NCSt -> Wake
  5,  % UVA -> UMD
  7   % Wake -> NCSt
];

% Days that are weekends (even days)
set of int: WEEKENDS = {d | d in DAYS where d mod 2 = 0};

% Days that are weekdays (odd days)
set of int: WEEKDAYS = {d | d in DAYS where d mod 2 = 1};

% Match configuration:
% For each day and team, the opponent team (0 if bye)
array[DAYS, TEAMS] of var 0..n_teams: config;

% Where: 0=bye, 1=home, 2=away
array[DAYS, TEAMS] of var 0..2: where;

% Helper: home team plays at home, away team plays away
% We will enforce config symmetry: if team i plays team j at home on day d,
% then team j plays team i away on day d.
% If config[d,i] = j > 0 and where[d,i] = 1 (home), then config[d,j] = i and where[d,j] = 2 (away)
% If config[d,i] = 0 then where[d,i] = 0 (bye)

% Constraint: no team plays itself
constraint forall(d in DAYS, t in TEAMS) (
  config[d,t] != t
);

% Constraint: if config[d,t] = 0 then where[d,t] = 0 (bye)
constraint forall(d in DAYS, t in TEAMS) (
  (config[d,t] = 0) <-> (where[d,t] = 0)
);

% Constraint: if config[d,t] = j > 0 then config[d,j] = t
constraint forall(d in DAYS, t in TEAMS) (
  let { var int: opp = config[d,t] } in
    if opp > 0 then config[d,opp] = t else true endif
);

% Constraint: if config[d,t] = j > 0 then where[d,t] != 0 and where[d,j] != 0
constraint forall(d in DAYS, t in TEAMS) (
  let { var int: opp = config[d,t] } in
    if opp > 0 then
      (where[d,t] != 0 /\ where[d,opp] != 0)
    else
      true
    endif
);

% Constraint: if config[d,t] = j > 0 and where[d,t] = 1 (home) then where[d,j] = 2 (away)
constraint forall(d in DAYS, t in TEAMS) (
  let { var int: opp = config[d,t] } in
    if opp > 0 then
      (where[d,t] = 1 -> where[d,opp] = 2) /\
      (where[d,t] = 2 -> where[d,opp] = 1)
    else
      true
    endif
);

% Constraint: each team plays each other twice: once home once away
% Count number of matches between i and j where i is home
constraint forall(i,j in TEAMS where i < j) (
  sum(d in DAYS)(bool2int(config[d,i] = j /\ where[d,i] = 1)) = 1 /\
  sum(d in DAYS)(bool2int(config[d,j] = i /\ where[d,j] = 1)) = 1
);

% Constraint: each team plays exactly one match or bye per day
constraint forall(d in DAYS, t in TEAMS) (
  % config[d,t] = 0 or opponent in 1..n_teams \ {t}
  % Already ensured by domain
  true
);

% Constraint: no team plays same opponent twice on same day (implied by config symmetry)

% Constraint: mirroring scheme
% For each pair (r1,r2), each team plays same opponent on both days
constraint forall(p in 1..9, t in TEAMS) (
  config[mirror_pairs[p,1], t] = config[mirror_pairs[p,2], t]
);

% Constraint: no two final aways
% No team can play away on both last dates (17 and 18)
constraint forall(t in TEAMS) (
  (where[17,t] = 2 /\ where[18,t] = 2) -> false
);

% Constraint: no more than two away matches in a row
constraint forall(t in TEAMS, d in 1..n_days-2) (
  sum(i in d..d+2)(bool2int(where[i,t] = 2)) <= 2
);

% Constraint: no more than two home matches in a row
constraint forall(t in TEAMS, d in 1..n_days-2) (
  sum(i in d..d+2)(bool2int(where[i,t] = 1)) <= 2
);

% Constraint: no more than three away matches or byes in a row
constraint forall(t in TEAMS, d in 1..n_days-3) (
  sum(i in d..d+3)(bool2int(where[i,t] = 0 \/ where[i,t] = 2)) <= 3
);

% Constraint: no more than four home matches or byes in a row
constraint forall(t in TEAMS, d in 1..n_days-4) (
  sum(i in d..d+4)(bool2int(where[i,t] = 0 \/ where[i,t] = 1)) <= 4
);

% Constraint: weekend pattern
% Each team plays 4 home, 4 away, 1 bye on weekends
constraint forall(t in TEAMS) (
  sum(d in WEEKENDS)(bool2int(where[d,t] = 1)) = 4 /\
  sum(d in WEEKENDS)(bool2int(where[d,t] = 2)) = 4 /\
  sum(d in WEEKENDS)(bool2int(where[d,t] = 0)) = 1
);

% Constraint: first weekends
% Each team must have home or bye at least on two of first five weekends
% First five weekends: days 2,4,6,8,10
set of int: first_five_weekends = {2,4,6,8,10};
constraint forall(t in TEAMS) (
  sum(d in first_five_weekends)(bool2int(where[d,t] = 1 \/ where[d,t] = 0)) >= 2
);

