    | 0, 3
    | 0, 4
    | 0, 4
    | 0, 4
    | 0, 5
    | 0, 4
    | 1, 3
    | 0, 2
];

// The board: 1 = shaded, 0 = empty
array[1..rows, 1..cols] of var 0..1: board;

// Helper function to get the sequence of blocks from a line
function array[int] of var int: get_blocks(var array[int] of var 0..1: line, int: max_blocks) =
    let {
        int: n = length(line),
        array[1..n] of var int: run_lengths = [if i == 1 then line[i] else if line[i] == 1 then run_lengths[i-1] + 1 else 0 endif endif | i in 1..n],
        array[1..n] of var int: block_id = [if line[i] == 1 then (if i == 1 then 1 else if line[i-1] == 0 then block_id[i-1] + 1 else block_id[i-1] endif endif) else 0 endif | i in 1..n]
    } in
    [max([if block_id[i] == b then run_lengths[i] else 0 endif | i in 1..n]) | b in 1..max_blocks];

// Constraint to enforce the blocks in a line match the given rules
predicate line_blocks(var array[int] of var 0..1: line, array[int] of int: rules, int: max_blocks) =
    let {
        array[int] of var int: blocks = get_blocks(line, max_blocks)
    } in
    forall(i in 1..max_blocks) (
        (rules[i] = 0 /\ blocks[i] = 0) \/
        (rules[i] > 0 /\ blocks[i] = rules[i])
    );

// Constraint to ensure blocks are separated by at least one zero
predicate blocks_separated(var array[int] of var 0..1: line, int: max_blocks, array[int] of int: rules) =
    let {
        int: n = length(line),
        array[1..n] of var int: block_id = [if line[i] == 1 then (if i == 1 then 1 else if line[i-1] == 0 then block_id[i-1] + 1 else block_id[i-1] endif endif) else 0 endif | i in 1..n]
    } in
    forall(b in 1..max_blocks where rules[b] > 0) (
        // block b must be contiguous and separated by zeros
        let {
            var int: start = min([i | i in 1..n where block_id[i] == b]),
            var int: end_ = max([i | i in 1..n where block_id[i] == b])
        } in
        forall(i in start..end_) (line[i] = 1)
    );

// Constraint to ensure no extra blocks beyond rules
predicate no_extra_blocks(var array[int] of var 0..1: line, int: max_blocks, array[int] of int: rules) =
    let {
        int: n = length(line),
        array[1..n] of var int: block_id = [if line[i] == 1 then (if i == 1 then 1 else if line[i-1] == 0 then block_id[i-1] + 1 else block_id[i-1] endif endif) else 0 endif | i in 1..n]
    } in
    forall(i in 1..n) (
        block_id[i] <= max_blocks
    ) /\
    forall(b in 1..max_blocks) (
        (rules[b] = 0) -> (not exists(i in 1..n)(block_id[i] = b))
    );

// Combine all line constraints
predicate line_constraint(var array[int] of var 0..1: line, array[int] of int: rules, int: max_blocks) =
    line_blocks(line, rules, max_blocks) /\
    blocks_separated(line, max_blocks, rules) /\
    no_extra_blocks(line, max_blocks, rules);

// Apply constraints for all rows
constraint
    forall(r in 1..rows) (
        line_constraint([board[r, c] | c in 1..cols], row_rules[r,], row_rule_len)
    );

// Apply constraints for all columns
constraint
    forall(c in 1..cols) (
        line_constraint([board[r, c] | r in 1..rows], col_rules[c,], col_rule_len)
    );

solve satisfy;

output [
    "{",
    "\"board\": [",
    concat([
        "[" ++ join(",", [show(board[r,c]) | c in 1..cols]) ++ "]" ++ if r < rows then "," else "" endif
        | r in 1..rows
    ]),
    "]",
    "}"
];
