include "globals.mzn";

int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

// Decision variables
array[1..n_boats] of var bool: is_host; // true if boat is host
// visits[p,b] = h means at period p, boat b visits host h (if b is guest)
array[1..n_periods, 1..n_boats] of var 1..n_boats: visits;

// Constraints

// A host visits itself at all periods
constraint
  forall(p in 1..n_periods, b in 1..n_boats) (
    if is_host[b] then
      visits[p,b] = b
    else
      true
    endif
  );

// Guests cannot visit non-hosts
constraint
  forall(p in 1..n_periods, b in 1..n_boats where not is_host[b]) (
    is_host[visits[p,b]]
  );

// Hosts do not visit other hosts (already fixed to themselves)
constraint
  forall(p in 1..n_periods, b in 1..n_boats where is_host[b]) (
    visits[p,b] = b
  );

// A guest cannot revisit the same host more than once
constraint
  forall(b in 1..n_boats where not is_host[b]) (
    forall(h1,h2 in 1..n_boats where h1 < h2) (
      (exists(p1 in 1..n_periods where visits[p1,b] = h1) /\
       exists(p2 in 1..n_periods where visits[p2,b] = h2)) -> true
    )
  );
