int: k = 4; % Number of sets
int: n = 4; % Numbers from 1 to n

int: length = k * n;

% The sequence to fill: positions 1..length
array[1..length] of var 1..n: solution;

% For each number m, we have k occurrences
% We want to arrange the k sets of numbers 1..n so that
% each appearance of number m is m numbers apart from the previous one.

% We model the positions of each occurrence of each number m
array[1..n, 1..k] of var 1..length: position;

% Link position and solution arrays
% For each number m and occurrence o, solution[position[m,o]] = m
constraint
  forall(m in 1..n, o in 1..k) (
    solution[position[m,o]] = m
  );

% All positions are distinct
constraint
  alldifferent([position[m,o] | m in 1..n, o in 1..k]);

% For each number m, the occurrences are spaced exactly m apart
% That is, for o in 1..k-1:
% position[m,o+1] = position[m,o] + m + 1
constraint
  forall(m in 1..n, o in 1..k-1) (
    position[m,o+1] = position[m,o] + m + 1
  );

% Positions must be within the sequence length
constraint
  forall(m in 1..n, o in 1..k) (
    position[m,o] >= 1 /\ position[m,o] <= length
  );

solve satisfy;

