include "globals.mzn";

int: n_teams = 8;
int: n_weeks = n_teams - 1;
int: n_periods = n_teams div 2;

// Teams are 0..n_teams-1
set of int: TEAMS = 0..n_teams-1;
set of int: WEEKS = 1..n_weeks;
set of int: PERIODS = 1..n_periods;

// home[w,p] and away[w,p] are the teams playing in week w, period p
array[WEEKS, PERIODS] of var TEAMS: home;
array[WEEKS, PERIODS] of var TEAMS: away;

// 1) Every team plays once a week (once in home or away per week)
constraint
  forall(w in WEEKS) (
    forall(t in TEAMS) (
      sum(p in PERIODS)(bool2int(home[w,p] = t) + bool2int(away[w,p] = t)) = 1
    )
  );

// 2) Every team plays at most twice in the same period over the tournament
constraint
  forall(t in TEAMS, p in PERIODS) (
    sum(w in WEEKS)(bool2int(home[w,p] = t) + bool2int(away[w,p] = t)) <= 2
  );

// 3) Every team plays every other team exactly once (home and away)
constraint
  forall(t1, t2 in TEAMS where t1 < t2) (
    sum(w in WEEKS, p in PERIODS)(
      bool2int(home[w,p] = t1 /\ away[w,p] = t2)
    ) = 1 /\
    sum(w in WEEKS, p in PERIODS)(
      bool2int(home[w,p] = t2 /\ away[w,p] = t1)
    ) = 0
  );

// Additional constraints to ensure no duplicate matches and no team plays itself
constraint
  forall(w in WEEKS, p in PERIODS) (
    home[w,p] != away[w,p]
  );

// All pairs (home[w,p], away[w,p]) are distinct matches (no duplicates)
constraint
  forall(w1, p1, w2, p2 in WEEKS, PERIODS where (w1,p1) < (w2,p2)) (
    (home[w1,p1] != home[w2,p2] \/ away[w1,p1] != away[w2,p2])
  );

// Symmetry breaking: fix first week matches to canonical order to reduce search
constraint
  forall(p in PERIODS) (
    home[1,p] = p-1 /\
    away[1,p] = n_teams - p
  );

// Now create the double round robin schedule by repeating the schedule with swapped home/away
array[1..2*n_weeks, PERIODS] of var TEAMS: home_double;
array[1..2*n_weeks, PERIODS] of var TEAMS: away_double;

constraint
  forall(w in WEEKS, p in PERIODS) (
    home_double[w,p] = home[w,p] /\
    away_double[w,p] = away[w,p]
  ) /\
  forall(w in WEEKS, p in PERIODS) (
    home_double[w + n_weeks, p] = away[w,p] /\
    away_double[w + n_weeks, p] = home[w,p]
  );

// Output the home and away schedules for the double round robin
output [
  "{",
  "\"home\": [",
  join(",\n", [
    "[" ++ join(", ", [show(home_double[w,p]) | p in PERIODS]) ++ "]"
    | w in 1..2*n_weeks
  ]),
  "],",
  "\"away\": [",
  join(",\n", [
    "[" ++ join(", ", [show(away_double[w,p]) | p in PERIODS]) ++ "]"
    | w in 1..2*n_weeks
  ]),
  "]",
  "}"
];
