include "globals.mzn";

int: n = 8; % Number of words to find
int: len = 8; % Length of each word

% Alphabet encoding: A=1, C=2, G=3, T=4
set of int: ALPH = 1..4;

% Complement mapping: A<->T, C<->G
array[ALPH] of ALPH: complement = [4,3,2,1];

% Words: n words of length len over ALPH
array[1..n, 1..len] of var ALPH: words;

% Constraint: each word has exactly 4 symbols from {C=2,G=3}
constraint
  forall(w in 1..n) (
    sum([bool2int(words[w,i] == 2 \/ words[w,i] == 3) | i in 1..len]) == 4
  );

% Hamming distance function between two words (arrays of var int)
function var int: hamming_dist(array[int] of var int: x, array[int] of var int: y) =
  sum(i in index_set(x)) (bool2int(x[i] != y[i]));

% Reverse function
function array[int] of var int: reverse_word(array[int] of var int: x) =
  [ x[len - i + 1] | i in 1..len ];

% Complement function
function array[int] of var int: complement_word(array[int] of var int: x) =
  [ complement[x[i]] | i in 1..len ];

% Constraints on pairs of distinct words: differ in at least 4 positions
constraint
  forall(i,j in 1..n where i < j) (
    hamming_dist([words[i,k] | k in 1..len], [words[j,k] | k in 1..len]) >= 4
  );

% Constraints on pairs (x,y): hamming distance between reverse(x) and complement(y) >= 4
constraint
  forall(i,j in 1..n) (
    hamming_dist(reverse_word([words[i,k] | k in 1..len]), complement_word([words[j,k] | k in 1..len])) >= 4
  );

solve satisfy;

output [
  "{",
  "\"words\": [",
  join(",\n", [
    "[" ++ join(",", [ if words[w,i] == 1 then "\"A\""
                     elseif words[w,i] == 2 then "\"C\""
                     elseif words[w,i] == 3 then "\"G\""
                     else "\"T\"" endif
                   | i in 1..len ]) ++ "]"
    | w in 1..n
  ]),
  "]",
  "}"
];
