constraint forall(i in 1..N) (
    adj[i,i] = 0
);

constraint forall(i,j in 1..N where i < j) (
    adj[i,j] = adj[j,i]
);

% Degree constraints: sum of adjacents = degree
constraint forall(i in 1..N) (
    sum(j in 1..N)(adj[i,j]) = deg[i]
);

% Diamond-free constraint:
% For every set of 4 distinct vertices, the number of edges among them <= 4
% The number of edges among 4 vertices is sum of adj[u,v] for all pairs u<v in the 4 vertices
set of int: V = 1..N;
