% Guests indexed as:
% 0: Andrew
% 1: Betty
% 2: Cara
% 3: Dave
% 4: Erica
% 5: Frank

int: n = 6;
set of int: GUESTS = 0..n-1;

% Seating order: seat 1 to 6
array[1..n] of var GUESTS: x;

% All guests seated exactly once
constraint
  all_different(x);

% Adjacency in the circular table: seat i adjacent to seat i-1 and i+1 modulo n
function int: left(int: i) = if i == 1 then n else i - 1 endif;
function int: right(int: i) = if i == n then 1 else i + 1 endif;

% Allowed neighbors for each guest
% Andrew(0): Dave(3), Frank(5)
% Betty(1): Cara(2), Erica(4)
% Cara(2): Betty(1), Frank(5)
% Dave(3): Andrew(0), Erica(4)
% Erica(4): Betty(1), Dave(3)
% Frank(5): Andrew(0), Cara(2)

array[GUESTS] of set of GUESTS: allowed_neighbors = [
  {3,5},    % Andrew
  {2,4},    % Betty
  {1,5},    % Cara
  {0,4},    % Dave
  {1,3},    % Erica
  {0,2}     % Frank
];

% Compute conflicts: 1 if neighbors not allowed, 0 otherwise
array[1..n] of var 0..1: conflict_left;
array[1..n] of var 0..1: conflict_right;

constraint
  forall(i in 1..n) (
    conflict_left[i] = if x[left(i)] in allowed_neighbors[x[i]] then 0 else 1 endif /\
    conflict_right[i] = if x[right(i)] in allowed_neighbors[x[i]] then 0 else 1 endif
  );

% Each conflict counted twice (once from each side), so total conflicts is sum of conflict_left divided by 2
var int: total_conflicts = sum(i in 1..n)(conflict_left[i]) div 2;

solve minimize total_conflicts;

output [
  "{",
  "\"x\": [" ++ join(", ", [show(x[i]) | i in 1..n]) ++ "]",
  "}"
];
```

