int: num_dice = 5;
int: faces = 6;

% Dice indices: 1=Rock, 2=Paper, 3=Scissors, 4=Lizard, 5=Spock
set of int: DICE = 1..num_dice;
set of int: FACES = 1..faces;

% The dominance relationships (winner, loser)
array[1..10, 1..2] of int: beats = [
    | 1, 3  % Rock crushes Scissors
    | 1, 4  % Rock crushes Lizard
    | 2, 1  % Paper covers Rock
    | 2, 5  % Paper disproves Spock
    | 3, 2  % Scissors cuts Paper
    | 3, 4  % Scissors decapitates Lizard
    | 4, 2  % Lizard eats Paper
    | 4, 5  % Lizard poisons Spock
    | 5, 1  % Spock vaporizes Rock
    | 5, 3  % Spock smashes Scissors
];

% Variables: dice[d,i] is the face value of die d on face i
array[DICE, FACES] of var 1..30: dice;

% To avoid symmetries, order faces within each die
constraint
  forall(d in DICE) (
    forall(i in 1..faces-1) (
      dice[d,i] < dice[d,i+1]
    )
  );

% To avoid symmetries, order dice by their minimum face value
constraint
  forall(d in 1..num_dice-1) (
    dice[d,1] < dice[d+1,1]
  );

% The key constraint: For each beats pair (winner, loser),
% the probability that winner beats loser is > 0.5
% i.e. number of pairs (w_face, l_face) with w_face > l_face > 18 (out of 36)

