int: total_weight = 40;
int: num_pieces = 4;

% The weights of the four pieces, sorted ascending
array[1..num_pieces] of var 1..total_weight: weights;

% The sum of the weights must be total_weight
constraint sum(i in 1..num_pieces)(weights[i]) == total_weight;

% Sort weights ascending
constraint forall(i in 1..num_pieces-1)(weights[i] <= weights[i+1]);

% We want to be able to weigh every integral weight from 1 to 40
% Using a balance scale, weights can be placed on either side.
% For each target weight w in 1..40, there must be a way to assign each piece
% to either left pan (-1), right pan (+1), or not used (0), so that
% sum of (assignment[i] * weights[i]) == w

% For each w, define an array of assignments for each piece: -1,0,1
array[1..total_weight, 1..num_pieces] of var -1..1: assignment;

% For each w, the weighted sum must equal w
constraint forall(w in 1..total_weight)(
    sum(i in 1..num_pieces)(assignment[w,i] * weights[i]) == w
);

% To avoid trivial solutions, enforce that at least one piece is used for each w
constraint forall(w in 1..total_weight)(
    exists(i in 1..num_pieces)(assignment[w,i] != 0)
);

solve satisfy;

output [
    "{",
    "\"weights\": [" ++ join(", ", [show(weights[i]) | i in 1..num_pieces]) ++ "]",
    "}"
];
```

