% Total cable length = sum over all connections of cables[i] * abs(pos[from_dev[i]] - pos[to_dev[i]])

var int: final_sum = sum(i in 1..NUM_CONNECTIONS) (
    cables[i] * abs(pos[from_dev[i]] - pos[to_dev[i]])
);

solve minimize final_sum;

output [
    "{",
    "\"final_sum\": " ++ show(final_sum),
    "}"
];
