include "globals.mzn";

int: n = 5;

array[1..n, 1..n] of var 1..n*n: x;

// Position of each number in the sequence
array[1..n*n] of var 1..n: row;
array[1..n*n] of var 1..n: col;

// Link positions and grid values
constraint
  forall(r in 1..n, c in 1..n) (
    x[r,c] = var int: v where v in 1..n*n /\ row[v] = r /\ col[v] = c
  );

// Enforce that row and col arrays are permutations of positions
// Actually, row and col are arrays of variables, each in 1..n, but we must ensure that
// for all v != w, (row[v], col[v]) != (row[w], col[w]) to ensure all positions are distinct.

constraint
  forall(v, w in 1..n*n where v < w) (
    row[v] != row[w] \/ col[v] != col[w]
  );

// Link x and (row, col)
constraint
  forall(v in 1..n*n) (
    x[row[v], col[v]] = v
  );

// Movement constraints between consecutive numbers
constraint
  forall(i in 1..n*n-1) (
    let {
      var int: dr = abs(row[i+1] - row[i]),
      var int: dc = abs(col[i+1] - col[i])
    } in
      // Movement Type I: vertical or horizontal, exactly 3 squares away (gap 2)
      // Movement Type II: diagonal, exactly 2 squares away (gap 1)
      (
        ( (dr = 3 /\ dc = 0) \/ (dr = 0 /\ dc = 3) )
        \/
        (dr = 2 /\ dc = 2)
      )
  );

// Symmetry breaking: fix the first number at (1,1)
constraint row[1] = 1 /\ col[1] = 1;

solve satisfy;

output [
  "[\n"
] ++
[
  "  [" ++ join(", ", [show(x[r,c]) | c in 1..n]) ++ "]" ++ if r < n then ",\n" else "\n" endif
  | r in 1..n
] ++
[
  "]"
];
```

