% For each amount from 1 to 99, we want to be able to pay exactly that amount
% using the coins in x. We model this by introducing auxiliary variables:
% For each amount a, variables y[a,c] = number of coins of denomination c used to pay amount a
array[1..max_amount, Coins] of var 0..max_amount: y;

% Constraints:
