% Actually, the problem is to find a minimal set of coins x such that for any amount a,
% there exists a combination y[a,*] <= x that sums to a.
% So for each c, y[a,c] <= x[c] for all a
constraint
  forall(a in 1..max_amount, c in Coins) (
    y[a,c] <= x[c]
  );

% Objective: minimize total number of coins
var int: total_coins = sum(c in Coins)(x[c]);
solve minimize total_coins;

output [
  "[", join(", ", [show(x[c]) | c in Coins]), "]"
];
