var 0..9: F = L[6];
var 0..9: G = L[7];
var 0..9: H = L[8];
var 0..9: I = L[9];
var 0..9: J = L[10];

constraint alldifferent(L);

% The addition is:
%   B A I J J A J I I A H F C F E B B J E A
% + D H F G A B C D I D B I F F A G F E J E
% -----------------------------------------
% = G J E G A C D D H F A F J B F I H E E F

% Let's write the numbers as arrays of digits, from left to right:
array[1..21] of var 0..9: addend1 = [B,A,I,J,J,A,J,I,I,A,H,F,C,F,E,B,B,J,E,A];
