int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1]; % 1 = tails, 0 = heads

% We have 3 coins, each can be 0 or 1
int: n = 3;

% steps[m] is the coin flipped at move m (1..n)
array[1..num_moves] of var 1..n: steps;

% state[m, c] is the state of coin c after move m (0 or 1)
array[0..num_moves, 1..n] of var 0..1: state;

% Initial state
constraint forall(c in 1..n) (
    state[0, c] = init[c]
);

% Each move flips exactly one coin
constraint forall(m in 1..num_moves) (
    forall(c in 1..n) (
        % If coin c is flipped at move m, its state toggles
        (steps[m] = c) -> (state[m, c] = 1 - state[m-1, c]) /\
        (steps[m] != c) -> (state[m, c] = state[m-1, c])
    )
);

% After num_moves, all coins are either all 0 or all 1
constraint
    (forall(c in 1..n)(state[num_moves, c] = 0) \/
     forall(c in 1..n)(state[num_moves, c] = 1));

solve satisfy;

output [
    "{",
    "\"steps\": [" ++ join(", ", [show(steps[m]) | m in 1..num_moves]) ++ "]",
    "}"
];
